import React, { useState, useEffect, useRef, useCallback } from 'react';
import { toast } from 'sonner';
import '../App.css';
import '../styles/FacePage.css';
import FaceCharacter from '../components/face/FaceCharacter';

// Конфигурация Vapi.ai
const VAPI_PUBLIC_KEY = '93241095-1999-4ac7-8030-c29bd6e9cca9';
const VAPI_ASSISTANT_ID = '4e444056-609a-4455-93ab-cbba9d620314';

const resolveBackendUrl = () => {
  if (process.env.REACT_APP_BACKEND_URL) {
    return process.env.REACT_APP_BACKEND_URL;
  }
  if (typeof window !== 'undefined' && window.location?.origin) {
    return window.location.origin;
  }
  if (process.env.NODE_ENV === 'development') {
    return 'http://localhost:8001';
  }
  return '';
};

const BACKEND_URL = resolveBackendUrl();

function MainPage() {
  const [messages, setMessages] = useState([]);
  const [inputMessage, setInputMessage] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [sessionId] = useState(() => `session_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`);
  const [isRecording, setIsRecording] = useState(false);
  const [voiceMode, setVoiceMode] = useState(false); // false = text/voice, true = realtime voice
  const [mediaRecorder, setMediaRecorder] = useState(null);
  const [, setRecordedAudio] = useState(null);
  const [isTranscribing, setIsTranscribing] = useState(false);
  const [voiceModeStatus, setVoiceModeStatus] = useState('disconnected'); // disconnected, connecting, connected
  const [capabilities, setCapabilities] = useState({});
  const [audioLevel, setAudioLevel] = useState(0);
  const [isListening, setIsListening] = useState(false);
  const [isSpeaking, setIsSpeaking] = useState(false); // AI говорит
  const [isConnecting, setIsConnecting] = useState(false);
  const [voiceError, setVoiceError] = useState(null);
  
  // Refs
  const vapiRef = useRef(null);
  const faceCharacterRef = useRef(null);
  const messagesEndRef = useRef(null);
  
  const isVoiceConnected = voiceModeStatus === 'connected';

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  useEffect(() => {
    // Load chat history and capabilities
    // loadChatHistory(); // History temporarily disabled for clean start
    loadCapabilities();
  }, []);

  // Инициализация Vapi при переключении в голосовой режим
  useEffect(() => {
    if (voiceMode && !vapiRef.current) {
      // Проверяем что Vapi SDK загружен
      if (typeof window.Vapi === 'undefined') {
        console.error('Vapi SDK не загружен!');
        setVoiceError('Vapi SDK не загружен. Перезагрузите страницу.');
        return;
      }

      // Создаем экземпляр Vapi
      const vapi = new window.Vapi(VAPI_PUBLIC_KEY);
      vapiRef.current = vapi;
      console.log('✅ Vapi инициализирован');

      // Подписываемся на события Vapi
      
      // Звонок начался
      vapi.on('call-start', () => {
        console.log('📞 Vapi: звонок начался');
        setVoiceModeStatus('connected');
        setIsListening(true);
        setVoiceError(null);
        setIsConnecting(false);
        toast.success('Голосовой режим активирован');
      });

      // Звонок завершен
      vapi.on('call-end', () => {
        console.log('📞 Vapi: звонок завершен');
        setVoiceModeStatus('disconnected');
        setIsListening(false);
        setIsSpeaking(false);
        setAudioLevel(0);
        setIsConnecting(false);
        toast.info('Голосовой режим отключен');
      });

      // AI начал говорить
      vapi.on('speech-start', () => {
        console.log('🔊 Vapi: AI начал говорить');
        setIsSpeaking(true);
        setIsListening(false);
      });

      // AI закончил говорить
      vapi.on('speech-end', () => {
        console.log('🔊 Vapi: AI закончил говорить');
        setIsSpeaking(false);
        setIsListening(true);
      });

      // Уровень громкости (для lip sync)
      vapi.on('volume-level', (level) => {
        setAudioLevel(level);
        if (faceCharacterRef.current) {
          faceCharacterRef.current.setAudioLevel(level);
        }
      });

      // Ошибка
      vapi.on('error', (err) => {
        console.error('❌ Vapi ошибка:', err);
        const errorMsg = err?.message || err?.error || 'Ошибка голосового режима';
        setVoiceError(errorMsg);
        setIsConnecting(false);
        toast.error(`Ошибка: ${errorMsg}`);
      });

      // Сообщение (для отладки)
      vapi.on('message', (message) => {
        console.log('📩 Vapi сообщение:', message);
      });
    }

    // Cleanup при выходе из голосового режима
    return () => {
      if (!voiceMode && vapiRef.current) {
        console.log('🧹 Очистка Vapi при выходе из голосового режима...');
        vapiRef.current.stop();
      }
    };
  }, [voiceMode]);

  // Cleanup при размонтировании компонента
  useEffect(() => {
    return () => {
      if (vapiRef.current) {
        vapiRef.current.stop();
      }
    };
  }, []);

  const loadCapabilities = async () => {
    try {
      const response = await fetch(`${BACKEND_URL}/api/capabilities`);
      if (response.ok) {
        const data = await response.json();
        setCapabilities(data);
        console.log('Backend capabilities:', data);
      }
    } catch (error) {
      console.error('Error loading capabilities:', error);
    }
  };

  const sendMessage = async (message = inputMessage) => {
    if (!message.trim()) return;

    const userMessage = {
      id: Date.now().toString(),
      content: message,
      role: 'user',
      timestamp: new Date().toISOString()
    };

    setMessages(prev => [...prev, userMessage]);
    setInputMessage('');
    setIsLoading(true);

    try {
      const response = await fetch(`${BACKEND_URL}/api/chat`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          session_id: sessionId,
          message: message
        })
      });

      if (response.ok) {
        const data = await response.json();
        const assistantMessage = {
          id: data.message_id,
          content: data.response,
          role: 'assistant',
          timestamp: new Date().toISOString()
        };
        setMessages(prev => [...prev, assistantMessage]);
      } else {
        throw new Error('Failed to send message');
      }
    } catch (error) {
      console.error('Error sending message:', error);
      const errorMessage = {
        id: Date.now().toString(),
        content: 'Извините, произошла ошибка при отправке сообщения.',
        role: 'assistant',
        timestamp: new Date().toISOString()
      };
      setMessages(prev => [...prev, errorMessage]);
    } finally {
      setIsLoading(false);
    }
  };

  const handleKeyPress = (e) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      sendMessage();
    }
  };

  const startRecording = async () => {
    // Legacy text-to-speech recording logic kept for text mode if needed
    try {
        const stream = await navigator.mediaDevices.getUserMedia({ 
          audio: {
            sampleRate: 16000,
            channelCount: 1,
            echoCancellation: true,
            noiseSuppression: true
          }
        });
        
        const recorder = new MediaRecorder(stream, {
          mimeType: 'audio/webm;codecs=opus'
        });
        
        const audioChunks = [];
        
        recorder.ondataavailable = (event) => {
          if (event.data.size > 0) {
            audioChunks.push(event.data);
          }
        };
        
        recorder.onstop = async () => {
          const audioBlob = new Blob(audioChunks, { type: 'audio/webm' });
          setRecordedAudio(audioBlob);
          stream.getTracks().forEach(track => track.stop());
          
          alert("Голосовой ввод в текстовом режиме временно недоступен. Пожалуйста, используйте Голосовой режим.");
        };
        
        recorder.start();
        setMediaRecorder(recorder);
        setIsRecording(true);
        
      } catch (error) {
        console.error('Error accessing microphone:', error);
        alert('Ошибка доступа к микрофону.');
      }
  };

  const stopRecording = () => {
    if (mediaRecorder && mediaRecorder.state === 'recording') {
      mediaRecorder.stop();
      setIsRecording(false);
    }
  };

  // Начать/завершить голосовой звонок через Vapi
  const toggleVoiceSession = async () => {
    if (isVoiceConnected) {
      // Завершить звонок
      if (vapiRef.current) {
        console.log('📞 Завершаем звонок...');
        vapiRef.current.stop();
      }
      return;
    }

    // Начать звонок
    try {
      if (!vapiRef.current) {
        // Инициализируем Vapi если еще не создан
        if (typeof window.Vapi === 'undefined') {
          setVoiceError('Vapi SDK не загружен. Перезагрузите страницу.');
          toast.error('Vapi SDK не загружен');
          return;
        }
        const vapi = new window.Vapi(VAPI_PUBLIC_KEY);
        vapiRef.current = vapi;
        
        // Подписка на события (дублируем если не было инициализации)
        vapi.on('call-start', () => {
          setVoiceModeStatus('connected');
          setIsListening(true);
          setVoiceError(null);
          setIsConnecting(false);
          toast.success('Голосовой режим активирован');
        });
        vapi.on('call-end', () => {
          setVoiceModeStatus('disconnected');
          setIsListening(false);
          setIsSpeaking(false);
          setAudioLevel(0);
          setIsConnecting(false);
        });
        vapi.on('speech-start', () => {
          setIsSpeaking(true);
          setIsListening(false);
        });
        vapi.on('speech-end', () => {
          setIsSpeaking(false);
          setIsListening(true);
        });
        vapi.on('volume-level', (level) => {
          setAudioLevel(level);
          if (faceCharacterRef.current) {
            faceCharacterRef.current.setAudioLevel(level);
          }
        });
        vapi.on('error', (err) => {
          const errorMsg = err?.message || err?.error || 'Ошибка голосового режима';
          setVoiceError(errorMsg);
          setIsConnecting(false);
          toast.error(`Ошибка: ${errorMsg}`);
        });
      }

      console.log('📞 Начинаем звонок...');
      setIsConnecting(true);
      setVoiceError(null);
      
      await vapiRef.current.start(VAPI_ASSISTANT_ID);
      
    } catch (err) {
      console.error('Ошибка при запуске звонка:', err);
      const errorMsg = err.message || 'Не удалось начать звонок';
      setVoiceError(errorMsg);
      setIsConnecting(false);
      toast.error(`Ошибка: ${errorMsg}`);
    }
  };

  const handleSwitchToTextMode = () => {
    setVoiceMode(false);
    // Завершаем звонок если идет
    if (vapiRef.current && isVoiceConnected) {
      vapiRef.current.stop();
    }
  };

  const handleSwitchToVoiceMode = () => {
    setVoiceMode(true);
  };

  const playTTS = async (text) => {
    // Simple browser TTS for now
    if ('speechSynthesis' in window) {
      const utterance = new SpeechSynthesisUtterance(text);
      utterance.lang = 'ru-RU';
      window.speechSynthesis.speak(utterance);
    }
  };

  const getVoiceModeStatusText = () => {
    if (isConnecting) return 'Подключение...';
    if (isSpeaking) return 'AI говорит...';
    if (isListening) return 'Слушаю вас';
    if (isVoiceConnected) return 'Подключено';
    return 'Отключено';
  };

  // Проверка доступности Vapi SDK
  const isVapiAvailable = typeof window !== 'undefined' && typeof window.Vapi !== 'undefined';

  return (
    <div className="app">
      {/* Header with Belarus symbols */}
      <header className="app-header">
        <div className="header-content">
          <div className="symbols">
            <img 
              src="https://customer-assets.emergentagent.com/job_belarus-constitution/artifacts/zbmwau2o_1613443720_6-p-fon-dlya-prezentatsii-pro-belarus-10.jpg" 
              alt="Флаг Беларуси" 
              className="flag"
            />
            <img 
              src="https://customer-assets.emergentagent.com/job_belarus-constitution/artifacts/nvezqned_Belarus_gerb_2021.jpg" 
              alt="Герб Беларуси" 
              className="coat-of-arms"
            />
          </div>
          <h1 className="title">AI-ассистент по Конституции Республики Беларусь</h1>
          <div className="mode-toggle">
            <button 
              className={`mode-btn ${!voiceMode ? 'active' : ''}`}
              onClick={handleSwitchToTextMode}
            >
              Текст/Голос
            </button>
            <button 
              className={`mode-btn ${voiceMode ? 'active' : ''}`}
              onClick={handleSwitchToVoiceMode}
            >
              Голосовой режим
            </button>
          </div>
        </div>
      </header>

      {voiceMode ? (
        <main className="voice-mode-main">
          <div className="voice-mode-container">
            <div className="voice-avatar-wrapper">
              <div className="voice-avatar-square">
                <FaceCharacter
                  ref={faceCharacterRef}
                  isSpeaking={isSpeaking}
                  audioLevel={audioLevel}
                />
              </div>
            </div>

            <div className="voice-mode-controls-centered">
              <div className="voice-status">
                <p>Голосовой режим в реальном времени</p>
                <div className={`status-indicator ${isConnecting ? 'connecting' : voiceModeStatus}`}>
                  <span className="status-dot"></span>
                  Статус: {getVoiceModeStatusText()}
                </div>
                {isVoiceConnected && (
                  <div className="audio-level-indicator">
                    <span role="img" aria-label="Аудио уровень">🔊</span>
                    <div className="audio-level-bar">
                      <div 
                        className="audio-level-fill" 
                        style={{ width: `${Math.min(1, audioLevel) * 100}%` }} 
                      />
                    </div>
                  </div>
                )}
                {voiceError && (
                  <div className="error-message">
                    {voiceError}
                  </div>
                )}
              </div>

              <div className="voice-controls-grid">
                <button
                  className={isVoiceConnected ? 'voice-disconnect-btn' : 'voice-connect-btn'}
                  onClick={toggleVoiceSession}
                  disabled={isConnecting || !isVapiAvailable}
                >
                  {!isVapiAvailable
                    ? 'Загрузка...'
                    : isVoiceConnected
                      ? 'Выключить голосовой режим'
                      : isConnecting
                        ? 'Подключаемся...'
                        : 'Включить голосовой режим'}
                </button>
              </div>
              <p className="voice-hint">
                💡 Можете перебивать ассистента в любой момент
              </p>
            </div>
          </div>
        </main>
      ) : (
        <main className="main-content">
          {/* Chat area */}
          <div className="chat-container">
            <div className="chat-messages">
              {messages.length === 0 && (
                <div className="welcome-message">
                  <p>Добро пожаловать! Меня зовут <strong>Алеся</strong>, и я помогу вам получить информацию по Конституции Республики Беларусь.</p>
                  <p>Задайте ваш вопрос текстом или голосом, и я отвечу согласно Конституции РБ редакции 2022 года.</p>
                </div>
              )}
              
              {messages.map((message) => (
                <div key={message.id} className={`message ${message.role}`}>
                  <div className="message-content">
                    <span className="message-text">{message.content}</span>
                    {message.role === 'assistant' && (
                      <button 
                        className="tts-btn"
                        onClick={() => playTTS(message.content)}
                        title="Озвучить ответ"
                      >
                        🔊
                      </button>
                    )}
                  </div>
                  <div className="message-time">
                    {new Date(message.timestamp).toLocaleTimeString('ru-RU')}
                  </div>
                </div>
              ))}
              
              {(isLoading || isTranscribing) && (
                <div className="message assistant">
                  <div className="message-content loading">
                    <span>{isTranscribing ? 'Распознавание речи...' : 'Ассистент думает...'}</span>
                    <div className="loading-dots">
                      <span></span>
                      <span></span>
                      <span></span>
                    </div>
                  </div>
                </div>
              )}
              <div ref={messagesEndRef} />
            </div>

            {/* Input area */}
            <div className="chat-input">
              <div className="input-container">
                <textarea
                  value={inputMessage}
                  onChange={(e) => setInputMessage(e.target.value)}
                  onKeyPress={handleKeyPress}
                  placeholder="Задайте ваш вопрос по Конституции Республики Беларусь..."
                  disabled={isLoading || isTranscribing}
                  rows="2"
                />
                <div className="input-buttons">
                  <button
                    className="send-btn"
                    onClick={() => sendMessage()}
                    disabled={isLoading || !inputMessage.trim() || isTranscribing}
                  >
                    Отправить
                  </button>
                </div>
              </div>
              {isRecording && (
                <div className="recording-indicator">
                  🔴 Запись... Отпустите кнопку чтобы отправить
                </div>
              )}
            </div>
          </div>

          {/* Avatar */}
          <div className="avatar-container">
            <img 
              src="https://customer-assets.emergentagent.com/job_belarus-constitution/artifacts/mqexhzvw_d3788255-d883-47b1-837f-751a2e82c62b.png" 
              alt="Ассистент" 
              className="avatar"
            />
          </div>
        </main>
      )}
    </div>
  );
}

export default MainPage;
